// ── URL CONVERTER ────────────────────────────────────────────
function getEmbedData(url) {
  url = url.trim();

  // YouTube
  let ytMatch = url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/shorts\/)([a-zA-Z0-9_-]{11})/);
  if (ytMatch) {
    const id = ytMatch[1];
    return {
      embedUrl: `https://www.youtube.com/embed/${id}?autoplay=1&rel=0`,
      thumbUrl: `https://img.youtube.com/vi/${id}/hqdefault.jpg`,
      type: 'youtube'
    };
  }

  // Google Drive
  let driveMatch = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([a-zA-Z0-9_-]+)/);
  if (driveMatch) {
    const id = driveMatch[1];
    return {
      embedUrl: `https://drive.google.com/file/d/${id}/preview`,
      thumbUrl: `https://drive.google.com/thumbnail?id=${id}&sz=w640`,
      type: 'drive'
    };
  }

  // Google Drive direct share link
  let driveShare = url.match(/drive\.google\.com\/.*\/([a-zA-Z0-9_-]{25,})/);
  if (driveShare) {
    const id = driveShare[1];
    return {
      embedUrl: `https://drive.google.com/file/d/${id}/preview`,
      thumbUrl: `https://drive.google.com/thumbnail?id=${id}&sz=w640`,
      type: 'drive'
    };
  }

  // Instagram
  let igMatch = url.match(/instagram\.com\/(?:p|reel|tv)\/([a-zA-Z0-9_-]+)/);
  if (igMatch) {
    return {
      embedUrl: `https://www.instagram.com/p/${igMatch[1]}/embed/`,
      thumbUrl: null,
      type: 'instagram'
    };
  }

  // Fallback — treat as embed directly
  return { embedUrl: url, thumbUrl: null, type: 'other' };
}

// ── RENDER GRID ──────────────────────────────────────────────
function renderGrid() {
  const grid = document.getElementById('videoGrid');
  grid.innerHTML = '';

  videos.forEach((v, We) => {
    const data = getEmbedData(v.url);
    const card = document.createElement('div');
    card.className = 'video-card fade-in';
    card.style.animationDelay = `${We * 0.08}s`;

    const thumbHtml = data.thumbUrl
      ? `<img src="${data.thumbUrl}" alt="${v.title}" loading="lazy" onerror="this.style.display='none'">`
      : `<div style="width:100%;height:100%;background:linear-gradient(135deg,#111,#1a1a1a);display:flex;align-items:center;justify-content:center;font-size:32px;">🎬</div>`;

    card.innerHTML = `
      <div class="video-thumb">
        ${thumbHtml}
        <div class="play-overlay">
          <div class="play-btn">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="#111"><polygon points="5,3 19,12 5,21"/></svg>
          </div>
        </div>
      </div>
      <div class="video-info">
        <span class="video-tag">${v.tag}</span>
        <p class="video-title">${v.title}</p>
        ${v.desc ? `<p class="video-desc">${v.desc}</p>` : ''}
      </div>
    `;

    card.addEventListener('click', () => openModal(v.title, data.embedUrl));
    grid.appendChild(card);
    setTimeout(() => card.classList.add('visible'), 50);
  });
}

// ── MODAL ────────────────────────────────────────────────────
function openModal(title, embedUrl) {
  document.getElementById('modalTitle').textContent = title;
  document.getElementById('modalIframe').src = embedUrl;
  document.getElementById('videoModal').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closeModalDirect() {
  document.getElementById('videoModal').classList.remove('open');
  document.getElementById('modalIframe').src = '';
  document.body.style.overflow = '';
}

function closeModal(e) {
  if (e.target === document.getElementById('videoModal')) closeModalDirect();
}

document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') closeModalDirect();
});

// ── ADD VIDEO ────────────────────────────────────────────────
function addVideo() {
  const title = document.getElementById('videoTitle').value.trim() || 'Untitled Project';
  const tag = document.getElementById('videoTag').value.trim() || 'Video';
  const url = document.getElementById('videoUrl').value.trim();
  const desc = document.getElementById('videoDesc').value.trim();

  if (!url) { alert('Please enter a video URL.'); return; }

  videos.unshift({ title, tag, url, desc });
  
  try { localStorage.setItem('samar_videos', JSON.stringify(videos)); } catch(e) {}

  document.getElementById('videoTitle').value = '';
  document.getElementById('videoTag').value = '';
  document.getElementById('videoUrl').value = '';
  document.getElementById('videoDesc').value = '';

  renderGrid();

  // Scroll to work section
  document.getElementById('work').scrollIntoView({ behavior: 'smooth' });
}

// ── FAQ ──────────────────────────────────────────────────────
function toggleFaq(btn) {
  const item = btn.closest('.faq-item');
  item.classList.toggle('open');
}

// ── INTERSECTION OBSERVER ────────────────────────────────────
const io = new IntersectionObserver((entries) => {
  entries.forEach(el => {
    if (el.isIntersecting) {
      el.target.classList.add('visible');
      io.unobserve(el.target);
    }
  });
}, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

function observeAll() {
  document.querySelectorAll('.fade-in').forEach(el => io.observe(el));
}

// ── INIT ─────────────────────────────────────────────────────
renderGrid();
observeAll();

// ── DARK / LIGHT MODE ─────────────────────────

const toggle = document.getElementById("themeToggle");

// Load saved theme
if (localStorage.getItem("theme") === "light") {
  document.body.classList.add("light-mode");
}

toggle.addEventListener("click", () => {
  document.body.classList.toggle("light-mode");

  if (document.body.classList.contains("light-mode")) {
    localStorage.setItem("theme", "light");
  } else {
    localStorage.setItem("theme", "dark");
  }
});

